  1→//! CipherBox FUSE filesystem implementation.
  2→//!
  3→//! Platform-agnostic data structures (InodeTable, MetadataCache, ContentCache,
  4→//! FileHandle) are shared across all platforms. Platform-specific mount/unmount
  5→//! and FUSE callback implementations are behind feature flags.
  6→
  7→pub mod inode;
  8→pub mod cache;
  9→pub mod file_handle;
 10→pub mod helpers;
 11→pub mod constants;
 12→pub mod error;
 13→
 14→// FUSE operations (macOS/Linux - fuser-based)
 15→#[cfg(feature = "fuse")]
 16→pub mod operations;
 17→#[cfg(feature = "fuse")]
 18→pub mod read_ops;
 19→#[cfg(feature = "fuse")]
 20→pub mod write_ops;
 21→#[cfg(feature = "fuse")]
 22→pub mod dir_ops;
 23→
 24→// Platform-specific modules
 25→pub mod platform;
 26→
 27→// Re-exports
 28→pub use inode::{InodeTable, InodeData};
 29→pub use cache::{MetadataCache, ContentCache};
 30→pub use file_handle::OpenFileHandle;
 31→pub use error::FuseError;
