 99→    /// Lightweight file context returned from open/create.
100→    /// References into CipherBoxFS.open_files via file handle ID.
101→    pub struct WinFspFileContext {
102→        pub fh: u64,
103→        pub ino: u64,
104→        pub is_dir: bool,
105→    }
