 1→//! AES-256-GCM encryption/decryption.
 2→//!
 3→//! Sealed format: IV (12 bytes) || Ciphertext || Auth Tag (16 bytes)
 4→//! This matches the TypeScript `sealAesGcm` output exactly.
 5→
 6→use aes_gcm::{
 7→    aead::{Aead, KeyInit},
 8→    Aes256Gcm, Nonce,
 9→};
10→
11→use crate::error::CryptoError;
12→use crate::utils::generate_iv;
13→
14→/// AES-256-GCM key size in bytes (256 bits).
15→pub const AES_KEY_SIZE: usize = 32;
16→
17→/// AES-GCM IV size in bytes (96 bits).
18→pub const AES_IV_SIZE: usize = 12;
19→
20→/// AES-GCM authentication tag size in bytes (128 bits).
21→pub const AES_TAG_SIZE: usize = 16;
22→
23→/// Minimum sealed data size: IV + auth tag (empty plaintext).
24→const MIN_SEALED_SIZE: usize = AES_IV_SIZE + AES_TAG_SIZE;
25→
26→/// Encrypt data using AES-256-GCM.
27→///
28→/// Returns ciphertext with 16-byte auth tag appended (same as Web Crypto API).
29→pub fn encrypt_aes_gcm(
30→    plaintext: &[u8],
31→    key: &[u8; 32],
32→    iv: &[u8; 12],
33→) -> Result<Vec<u8>, CryptoError> {
34→    let cipher = Aes256Gcm::new_from_slice(key).map_err(|_| CryptoError::AesEncryptionFailed)?;
35→    let nonce = Nonce::from_slice(iv);
36→
37→    cipher
38→        .encrypt(nonce, plaintext)
39→        .map_err(|_| CryptoError::AesEncryptionFailed)
40→}
41→
42→/// Decrypt data using AES-256-GCM.
43→///
44→/// Expects ciphertext with 16-byte auth tag appended.
45→pub fn decrypt_aes_gcm(
46→    ciphertext: &[u8],
47→    key: &[u8; 32],
48→    iv: &[u8; 12],
49→) -> Result<Vec<u8>, CryptoError> {
50→    let cipher = Aes256Gcm::new_from_slice(key).map_err(|_| CryptoError::AesDecryptionFailed)?;
51→    let nonce = Nonce::from_slice(iv);
52→
53→    cipher
54→        .decrypt(nonce, ciphertext)
55→        .map_err(|_| CryptoError::AesDecryptionFailed)
56→}
57→
58→/// Seal data using AES-256-GCM with automatic IV generation.
59→///
60→/// Returns: IV (12 bytes) || Ciphertext || Auth Tag (16 bytes)
61→/// This format matches the TypeScript `sealAesGcm` exactly.
62→pub fn seal_aes_gcm(plaintext: &[u8], key: &[u8; 32]) -> Result<Vec<u8>, CryptoError> {
63→    let iv = generate_iv();
64→    let ciphertext = encrypt_aes_gcm(plaintext, key, &iv)?;
65→
66→    // IV || ciphertext (which already includes the tag)
67→    let mut sealed = Vec::with_capacity(AES_IV_SIZE + ciphertext.len());
68→    sealed.extend_from_slice(&iv);
69→    sealed.extend_from_slice(&ciphertext);
70→    Ok(sealed)
71→}
72→
73→/// Unseal data encrypted with `seal_aes_gcm`.
74→///
75→/// Extracts IV from first 12 bytes, decrypts remainder.
76→pub fn unseal_aes_gcm(sealed: &[u8], key: &[u8; 32]) -> Result<Vec<u8>, CryptoError> {
77→    if sealed.len() < MIN_SEALED_SIZE {
78→        return Err(CryptoError::AesDecryptionFailed);
79→    }
80→
81→    let iv: [u8; 12] = sealed[..AES_IV_SIZE]
82→        .try_into()
83→        .map_err(|_| CryptoError::AesDecryptionFailed)?;
84→    let ciphertext = &sealed[AES_IV_SIZE..];
85→
86→    decrypt_aes_gcm(ciphertext, key, &iv)
87→}
88→

  1→//! AES-256-CTR encryption/decryption.
  2→//!
  3→//! Symmetric encryption for media file content using CTR mode.
  4→//! CTR mode enables random-access decryption (any byte range without
  5→//! processing preceding bytes), required for streaming media playback.
  6→//!
  7→//! Uses Ctr64BE (big-endian 64-bit counter) to match Web Crypto API's
  8→//! `AES-CTR` with `length: 64`.
  9→//!
 10→//! SECURITY NOTE: AES-CTR does NOT provide authentication (unlike GCM).
 11→//! Integrity is provided by IPFS content addressing.
 12→
 13→use aes::Aes256;
 14→use ctr::cipher::{KeyIvInit, StreamCipher};
 15→
 16→use crate::error::CryptoError;
 17→
 18→/// AES-CTR IV size in bytes (128-bit counter block).
 19→pub const AES_CTR_IV_SIZE: usize = 16;
 20→
 21→/// AES block size in bytes.
 22→const AES_BLOCK_SIZE: usize = 16;
 23→
 24→/// Type alias for AES-256-CTR with 64-bit big-endian counter.
 25→/// Matches Web Crypto API's `AES-CTR` with `length: 64`.
 26→type Aes256Ctr64BE = ctr::Ctr64BE<Aes256>;
 27→
 28→/// Encrypt data using AES-256-CTR.
 29→///
 30→/// Each encryption MUST use a unique IV (nonce + counter) with the same key.
 31→/// Reusing nonce+key pairs is catastrophic for AES-CTR security.
 32→///
 33→/// CTR output is the same size as the input (no authentication tag).
 34→pub fn encrypt_aes_ctr(
 35→    plaintext: &[u8],
 36→    key: &[u8; 32],
 37→    iv: &[u8; 16],
 38→) -> Result<Vec<u8>, CryptoError> {
 39→    let mut cipher =
 40→        Aes256Ctr64BE::new(key.into(), iv.into());
 41→
 42→    let mut output = plaintext.to_vec();
 43→    cipher.apply_keystream(&mut output);
 44→
 45→    Ok(output)
 46→}
 47→
 48→/// Decrypt data encrypted with AES-256-CTR.
 49→///
 50→/// CTR encrypt == decrypt (XOR is symmetric), but provided as a separate
 51→/// function for API clarity.
 52→pub fn decrypt_aes_ctr(
 53→    ciphertext: &[u8],
 54→    key: &[u8; 32],
 55→    iv: &[u8; 16],
 56→) -> Result<Vec<u8>, CryptoError> {
 57→    // CTR mode: decrypt is identical to encrypt
 58→    encrypt_aes_ctr(ciphertext, key, iv)
 59→}
 60→
 61→/// Decrypt an arbitrary byte range from AES-256-CTR encrypted data.
 62→///
 63→/// Computes the correct counter value for any byte offset and decrypts
 64→/// only the required blocks, avoiding the need to process the entire file.
 65→///
 66→/// The counter is computed as: baseCounter + floor(startByte / 16)
 67→/// where baseCounter is the initial counter value from the IV (bytes 8-15).
 68→///
 69→/// `ciphertext` must contain at least the block-aligned range covering
 70→/// `[start_byte, end_byte]` (inclusive).
 71→pub fn decrypt_aes_ctr_range(
 72→    ciphertext: &[u8],
 73→    key: &[u8; 32],
 74→    iv: &[u8; 16],
 75→    start_byte: usize,
 76→    end_byte: usize,
 77→) -> Result<Vec<u8>, CryptoError> {
 78→    if start_byte > end_byte {
 79→        return Err(CryptoError::InvalidRange);
 80→    }
 81→
 82→    if ciphertext.is_empty() || start_byte >= ciphertext.len() {
 83→        return Ok(Vec::new());
 84→    }
 85→
 86→    // Clamp end_byte to actual data
 87→    let clamped_end = end_byte.min(ciphertext.len().saturating_sub(1));
 88→    if clamped_end < start_byte {
 89→        // Range is entirely beyond available data
 90→        return Ok(Vec::new());
 91→    }
 92→
 93→    // Compute block-aligned range
 94→    let start_block = start_byte / AES_BLOCK_SIZE;
 95→    let end_block = clamped_end / AES_BLOCK_SIZE;
 96→    let block_aligned_start = start_block * AES_BLOCK_SIZE;
 97→    let block_aligned_end = ((end_block + 1) * AES_BLOCK_SIZE).min(ciphertext.len());
 98→
 99→    // Build counter for starting block:
100→    // Copy nonce (first 8 bytes of IV), compute counter = baseCounter + startBlock
101→    let mut counter = [0u8; 16];
102→    counter[..8].copy_from_slice(&iv[..8]);
103→
104→    let base_counter = u64::from_be_bytes(iv[8..16].try_into().unwrap());
105→    let new_counter = base_counter.wrapping_add(start_block as u64);
106→    counter[8..16].copy_from_slice(&new_counter.to_be_bytes());
107→
108→    // Create cipher with adjusted counter
109→    let mut cipher = Aes256Ctr64BE::new(key.into(), &counter.into());
110→
111→    // Decrypt the block-aligned range
112→    let mut decrypted = ciphertext[block_aligned_start..block_aligned_end].to_vec();
113→    cipher.apply_keystream(&mut decrypted);
114→
115→    // Extract exact requested bytes from decrypted block-aligned data
116→    let offset_in_first_block = start_byte - block_aligned_start;
117→    let requested_length = clamped_end - start_byte + 1;
118→    let result = decrypted[offset_in_first_block..offset_in_first_block + requested_length].to_vec();
119→
120→    Ok(result)
121→}
