  1→//! IPNS name derivation (CIDv1 base36 from Ed25519 public key).
  2→//!
  3→//! This module extracts only the pure IPNS name derivation logic.
  4→//! IPNS record creation/marshaling stays in the desktop app (or cipherbox-core)
  5→//! because it involves domain-specific types and CBOR/protobuf encoding.
  6→
  7→use crate::error::CryptoError;
  8→
  9→/// Encode the Ed25519 public key in libp2p PublicKey protobuf format.
 10→///
 11→/// message PublicKey { KeyType Type = 1; bytes Data = 2; }
 12→/// where KeyType.Ed25519 = 1
 13→pub fn encode_libp2p_public_key(ed25519_public_key: &[u8]) -> Vec<u8> {
 14→    let mut buf = Vec::new();
 15→    // Field 1 (Type): varint, field_number=1, wire_type=0 => tag = 0x08
 16→    buf.push(0x08);
 17→    // Value: 1 (Ed25519)
 18→    buf.push(0x01);
 19→    // Field 2 (Data): length-delimited, field_number=2, wire_type=2 => tag = 0x12
 20→    buf.push(0x12);
 21→    // Length of public key (32 bytes)
 22→    buf.push(ed25519_public_key.len() as u8);
 23→    buf.extend_from_slice(ed25519_public_key);
 24→    buf
 25→}
 26→
 27→/// Derive the IPNS name (CIDv1 base36) from an Ed25519 public key.
 28→///
 29→/// Steps:
 30→/// 1. Wrap public key in libp2p PublicKey protobuf
 31→/// 2. Create identity multihash: 0x00 (identity) + varint(len) + data
 32→/// 3. Create CIDv1: version=1, codec=0x72 (libp2p-key), multihash
 33→/// 4. Encode as base36 (k... prefix)
 34→pub fn derive_ipns_name(ed25519_public_key: &[u8; 32]) -> Result<String, CryptoError> {
 35→    // Step 1: Wrap in libp2p PublicKey protobuf
 36→    let libp2p_pub_key = encode_libp2p_public_key(ed25519_public_key);
 37→
 38→    // Step 2: Create identity multihash
 39→    // Identity multihash: code=0x00, length=varint(data.len()), data
 40→    let mut identity_multihash = Vec::new();
 41→    identity_multihash.push(0x00); // identity hash function code
 42→    // Encode length as unsigned varint
 43→    encode_unsigned_varint(&mut identity_multihash, libp2p_pub_key.len() as u64);
 44→    identity_multihash.extend_from_slice(&libp2p_pub_key);
 45→
 46→    // Step 3: Create CIDv1
 47→    // CIDv1 binary: version(1) + codec(0x72, libp2p-key) + multihash
 48→    let mut cid_bytes = Vec::new();
 49→    encode_unsigned_varint(&mut cid_bytes, 1); // CID version 1
 50→    encode_unsigned_varint(&mut cid_bytes, 0x72); // libp2p-key codec
 51→    cid_bytes.extend_from_slice(&identity_multihash);
 52→
 53→    // Step 4: Encode as base36 with 'k' prefix
 54→    let base36 = encode_base36(&cid_bytes);
 55→    Ok(format!("k{}", base36))
 56→}
 57→
 58→/// Encode unsigned varint (same as protobuf varint / LEB128).
 59→fn encode_unsigned_varint(buf: &mut Vec<u8>, mut value: u64) {
 60→    loop {
 61→        let byte = (value & 0x7f) as u8;
 62→        value >>= 7;
 63→        if value == 0 {
 64→            buf.push(byte);
 65→            break;
 66→        } else {
 67→            buf.push(byte | 0x80);
 68→        }
 69→    }
 70→}
 71→
 72→/// Encode bytes as base36 (lowercase).
 73→///
 74→/// Base36 alphabet: REDACTED
 75→fn encode_base36(data: &[u8]) -> String {
 76→    if data.is_empty() {
 77→        return String::new();
 78→    }
 79→
 80→    const ALPHABET: &[u8; 36] = b"REDACTED";
 81→
 82→    // Count leading zeros
 83→    let leading_zeros = data.iter().take_while(|&&b| b == 0).count();
 84→
 85→    // Convert byte array to big integer using repeated division
 86→    let mut num = data.to_vec();
 87→    let mut result = Vec::new();
 88→
 89→    while !num.is_empty() {
 90→        let mut remainder: u32 = 0;
 91→        let mut quotient = Vec::new();
 92→
 93→        for &byte in &num {
 94→            let acc = (remainder << 8) | (byte as u32);
 95→            let digit = acc / 36;
 96→            remainder = acc % 36;
 97→
 98→            if !quotient.is_empty() || digit > 0 {
 99→                quotient.push(digit as u8);
100→            }
101→        }
102→
103→        result.push(ALPHABET[remainder as usize]);
104→        num = quotient;
105→    }
106→
107→    // Add leading '0's for each leading zero byte
108→    for _ in 0..leading_zeros {
109→        result.push(b'0');
110→    }
111→
112→    result.reverse();
113→    String::from_utf8(result).unwrap_or_default()
114→}
