 1→//! Shared decrypt functions for folder and file metadata.
 2→//! Used by CipherBoxFS::drain_refresh_completions() which is platform-agnostic.
 3→
 4→use crate::folder::{FolderMetadata, FileMetadata};
 5→
 6→/// Decrypt folder metadata from IPFS encrypted format.
 7→///
 8→/// All folder metadata (including root) uses v1 JSON `{"iv":"...","data":"..."}`.
 9→/// The v2 blob format is only used for the vault key blob (separate IPNS name).
10→pub fn decrypt_metadata_from_ipfs_public(
11→    encrypted_bytes: &[u8],
12→    folder_key: &[u8],
13→) -> Result<FolderMetadata, String> {
14→    let json_portion = encrypted_bytes;
15→
16→    #[derive(serde::Deserialize)]
17→    struct EncryptedFolderMetadata {
18→        iv: String,
19→        data: String,
20→    }
21→
22→    let encrypted: EncryptedFolderMetadata = serde_json::from_slice(json_portion)
23→        .map_err(|e| format!("Failed to parse encrypted metadata JSON: {}", e))?;
24→
25→    let iv_bytes =
26→        hex::decode(&encrypted.iv).map_err(|_| "Invalid metadata IV hex".to_string())?;
27→    if iv_bytes.len() != 12 {
28→        return Err(format!(
29→            "Invalid IV length: {} (expected 12)",
30→            iv_bytes.len()
31→        ));
32→    }
33→    let iv: [u8; 12] = iv_bytes.try_into().unwrap();
34→
35→    use base64::Engine;
36→    let ciphertext = base64::engine::general_purpose::STANDARD
37→        .decode(&encrypted.data)
38→        .map_err(|e| format!("Invalid metadata base64: {}", e))?;
39→
40→    let folder_key_arr: [u8; 32] = folder_key
41→        .try_into()
42→        .map_err(|_| "Invalid folder key length".to_string())?;
43→
44→    // Reconstruct sealed format: IV || ciphertext (includes tag)
45→    let mut sealed = Vec::with_capacity(12 + ciphertext.len());
46→    sealed.extend_from_slice(&iv);
47→    sealed.extend_from_slice(&ciphertext);
48→
49→    crate::folder::decrypt_folder_metadata(&sealed, &folder_key_arr)
50→        .map_err(|e| format!("Metadata decryption failed: {}", e))
51→}
52→
53→/// Decrypt file metadata from IPFS encrypted JSON format.
54→pub fn decrypt_file_metadata_from_ipfs_public(
55→    encrypted_bytes: &[u8],
56→    folder_key: &[u8; 32],
57→) -> Result<FileMetadata, String> {
58→    #[derive(serde::Deserialize)]
59→    struct EncryptedFolderMetadata {
60→        iv: String,
61→        data: String,
62→    }
63→
64→    let encrypted: EncryptedFolderMetadata = serde_json::from_slice(encrypted_bytes)
65→        .map_err(|e| format!("Failed to parse encrypted file metadata JSON: {}", e))?;
66→
67→    let iv_bytes = hex::decode(&encrypted.iv)
68→        .map_err(|_| "Invalid file metadata IV hex".to_string())?;
69→    if iv_bytes.len() != 12 {
70→        return Err(format!(
71→            "Invalid IV length: {} (expected 12)",
72→            iv_bytes.len()
73→        ));
74→    }
75→    let iv: [u8; 12] = iv_bytes.try_into().unwrap();
76→
77→    use base64::Engine;
78→    let ciphertext = base64::engine::general_purpose::STANDARD
79→        .decode(&encrypted.data)
80→        .map_err(|e| format!("Invalid file metadata base64: {}", e))?;
81→
82→    // Reconstruct sealed format: IV || ciphertext (includes tag)
83→    let mut sealed = Vec::with_capacity(12 + ciphertext.len());
84→    sealed.extend_from_slice(&iv);
85→    sealed.extend_from_slice(&ciphertext);
86→
87→    crate::folder::decrypt_file_metadata(&sealed, folder_key)
88→        .map_err(|e| format!("File metadata decryption failed: {}", e))
89→}
90→

  1→//! IPNS record creation and marshaling.
  2→//!
  3→//! Produces IPNS records compatible with the TypeScript `ipns` npm package output.
  4→//! - CBOR-encoded data field with V2 signature
  5→//! - Protobuf-encoded IpnsEntry for marshaling
  6→//!
  7→//! IPNS name derivation has been extracted to the `cipherbox-crypto` crate
  8→//! (see `cipherbox_crypto::ipns_name::derive_ipns_name`).
  9→
 10→use std::time::{Duration, SystemTime, UNIX_EPOCH};
 11→
 12→use ciborium::Value as CborValue;
 13→use thiserror::Error;
 14→
 15→use cipherbox_crypto::ed25519::{get_public_key, sign_ed25519};
 16→use cipherbox_crypto::ipns_name::encode_libp2p_public_key;
 17→
 18→// Re-export derive_ipns_name for backward compatibility (tests and other code
 19→// that reference `crate::crypto::ipns::derive_ipns_name`).
 20→pub use cipherbox_crypto::ipns_name::derive_ipns_name;
 21→
 22→/// IPNS signature prefix per IPFS spec: "ipns-signature:".
 23→const IPNS_SIGNATURE_PREFIX: &[u8] = b"ipns-signature:";
 24→
 25→/// Default IPNS record TTL: 300 seconds (5 minutes) in nanoseconds.
 26→/// This matches the ipns npm package default.
 27→const DEFAULT_TTL_NS: u64 = 300_000_000_000;
 28→
 29→#[derive(Debug, Error)]
 30→pub enum IpnsError {
 31→    #[error("IPNS record creation failed")]
 32→    CreationFailed,
 33→    #[error("IPNS record marshaling failed")]
 34→    MarshalingFailed,
 35→    #[error("Invalid private key")]
 36→    InvalidPrivateKey,
 37→    #[error("Invalid public key")]
 38→    InvalidPublicKey,
 39→    #[error("CBOR encoding failed")]
 40→    CborEncodingFailed,
 41→    #[error("Signing failed")]
 42→    SigningFailed,
 43→}
 44→
 45→/// IPNS record structure matching the TypeScript IPNSRecord type.
 46→#[derive(Debug, Clone)]
 47→pub struct IpnsRecord {
 48→    /// IPFS path value (e.g., "/ipfs/bafy...").
 49→    pub value: String,
 50→    /// RFC3339 validity timestamp with nanosecond precision.
 51→    pub validity: String,
 52→    /// Validity type (0 = EOL).
 53→    pub validity_type: u32,
 54→    /// Monotonically increasing sequence number.
 55→    pub sequence: u64,
 56→    /// TTL in nanoseconds.
 57→    pub ttl: u64,
 58→    /// 64-byte Ed25519 V1 signature.
 59→    pub signature_v1: Vec<u8>,
 60→    /// 64-byte Ed25519 V2 signature.
 61→    pub signature_v2: Vec<u8>,
 62→    /// CBOR-encoded record data.
 63→    pub data: Vec<u8>,
 64→    /// 32-byte Ed25519 public key.
 65→    pub public_key: Vec<u8>,
 66→}
 67→
 68→/// Build the CBOR-encoded data field for an IPNS record.
 69→///
 70→/// The field order matches the ipns npm package: TTL, Value, Sequence, Validity, ValidityType.
 71→/// Keys are strings, values match the types used by the ipns package.
 72→fn build_cbor_data(
 73→    value: &str,
 74→    validity: &str,
 75→    sequence: u64,
 76→    ttl: u64,
 77→) -> Result<Vec<u8>, IpnsError> {
 78→    let cbor_map = CborValue::Map(vec![
 79→        (
 80→            CborValue::Text("TTL".to_string()),
 81→            CborValue::Integer(ttl.into()),
 82→        ),
 83→        (
 84→            CborValue::Text("Value".to_string()),
 85→            CborValue::Bytes(value.as_bytes().to_vec()),
 86→        ),
 87→        (
 88→            CborValue::Text("Sequence".to_string()),
 89→            CborValue::Integer(sequence.into()),
 90→        ),
 91→        (
 92→            CborValue::Text("Validity".to_string()),
 93→            CborValue::Bytes(validity.as_bytes().to_vec()),
 94→        ),
 95→        (
 96→            CborValue::Text("ValidityType".to_string()),
 97→            CborValue::Integer(0.into()),
 98→        ),
 99→    ]);
100→
101→    let mut buf = Vec::new();
102→    ciborium::into_writer(&cbor_map, &mut buf).map_err(|_| IpnsError::CborEncodingFailed)?;
103→    Ok(buf)
104→}
105→
106→/// Format a timestamp as RFC3339 with nanosecond precision matching the ipns npm package.
107→///
108→/// The ipns package uses format: "2026-02-08T23:31:12.138000000Z"
109→fn format_validity_timestamp(validity_time: SystemTime) -> String {
110→    let duration = validity_time
111→        .duration_since(UNIX_EPOCH)
112→        .unwrap_or(Duration::ZERO);
113→    let secs = duration.as_secs();
114→    let nanos = duration.subsec_nanos();
115→
116→    let days = secs / 86400;
117→    let time_of_day = secs % 86400;
118→    let hours = time_of_day / 3600;
119→    let minutes = (time_of_day % 3600) / 60;
120→    let seconds = time_of_day % 60;
121→
122→    let (year, month, day) = civil_from_days(days as i64);
123→
124→    format!(
125→        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:09}Z",
126→        year, month, day, hours, minutes, seconds, nanos
127→    )
128→}
129→
130→/// Convert days since Unix epoch to (year, month, day).
131→/// Algorithm from Howard Hinnant's civil_from_days.
132→fn civil_from_days(days: i64) -> (i64, u32, u32) {
133→    let z = days + 719468;
134→    let era = if z >= 0 { z } else { z - 146096 } / 146097;
135→    let doe = (z - era * 146097) as u64;
136→    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
137→    let y = (yoe as i64) + era * 400;
138→    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
139→    let mp = (5 * doy + 2) / 153;
140→    let d = doy - (153 * mp + 2) / 5 + 1;
141→    let m = if mp < 10 { mp + 3 } else { mp - 9 };
142→    let y = if m <= 2 { y + 1 } else { y };
143→    (y, m as u32, d as u32)
144→}
145→
146→/// Compute the V1 signature.
147→///
148→/// Per IPNS spec, V1 signature is over: value_bytes + validity_bytes + varint(validityType)
149→fn compute_v1_signature(
150→    ed25519_private_key: &[u8; 32],
151→    value: &str,
152→    validity: &str,
153→) -> Result<Vec<u8>, IpnsError> {
154→    let mut data_to_sign = Vec::new();
155→    data_to_sign.extend_from_slice(value.as_bytes());
156→    data_to_sign.extend_from_slice(validity.as_bytes());
157→    data_to_sign.push(0x00);
158→
159→    sign_ed25519(&data_to_sign, ed25519_private_key).map_err(|_| IpnsError::SigningFailed)
160→}
161→
162→/// Compute the V2 signature.
163→///
164→/// Per IPNS spec, V2 signature is over: "ipns-signature:" + cbor_data
165→fn compute_v2_signature(
166→    ed25519_private_key: &[u8; 32],
167→    cbor_data: &[u8],
168→) -> Result<Vec<u8>, IpnsError> {
169→    let mut data_to_sign = Vec::with_capacity(IPNS_SIGNATURE_PREFIX.len() + cbor_data.len());
170→    data_to_sign.extend_from_slice(IPNS_SIGNATURE_PREFIX);
171→    data_to_sign.extend_from_slice(cbor_data);
172→
173→    sign_ed25519(&data_to_sign, ed25519_private_key).map_err(|_| IpnsError::SigningFailed)
174→}
175→
176→/// Create an IPNS record signed with the given Ed25519 private key.
177→///
178→/// Matches the TypeScript `createIpnsRecord` with `v1Compatible: true`.
179→pub fn create_ipns_record(
180→    ed25519_private_key: &[u8; 32],
181→    value: &str,
182→    sequence_number: u64,
183→    lifetime_ms: u64,
184→) -> Result<IpnsRecord, IpnsError> {
185→    let public_key = get_public_key(ed25519_private_key).map_err(|_| IpnsError::InvalidPrivateKey)?;
186→
187→    let now = SystemTime::now();
188→    let lifetime_duration = Duration::from_millis(lifetime_ms);
189→    let validity_time = now + lifetime_duration;
190→    let validity = format_validity_timestamp(validity_time);
191→
192→    let ttl = DEFAULT_TTL_NS;
193→
194→    let cbor_data = build_cbor_data(value, &validity, sequence_number, ttl)?;
195→
196→    let signature_v2 = compute_v2_signature(ed25519_private_key, &cbor_data)?;
197→
198→    let signature_v1 = compute_v1_signature(ed25519_private_key, value, &validity)?;
199→
200→    Ok(IpnsRecord {
201→        value: value.to_string(),
202→        validity,
203→        validity_type: 0,
204→        sequence: sequence_number,
205→        ttl,
206→        signature_v1,
207→        signature_v2,
208→        data: cbor_data,
209→        public_key,
210→    })
211→}
212→
213→/// Marshal an IPNS record to protobuf bytes.
214→///
215→/// IpnsEntry protobuf fields:
216→/// - field 1 (bytes): Value
217→/// - field 2 (bytes): signatureV1
218→/// - field 3 (enum): ValidityType (0 = EOL)
219→/// - field 4 (bytes): Validity (RFC3339 as bytes)
220→/// - field 5 (uint64): Sequence
221→/// - field 6 (uint64): TTL (nanoseconds)
222→/// - field 7 (bytes): pubKey (libp2p protobuf-wrapped Ed25519 public key)
223→/// - field 8 (bytes): signatureV2
224→/// - field 9 (bytes): data (CBOR)
225→pub fn marshal_ipns_record(record: &IpnsRecord) -> Result<Vec<u8>, IpnsError> {
226→    let mut buf = Vec::new();
227→
228→    encode_proto_bytes(&mut buf, 1, record.value.as_bytes());
229→    encode_proto_bytes(&mut buf, 2, &record.signature_v1);
230→    encode_proto_varint(&mut buf, 3, record.validity_type as u64);
231→    encode_proto_bytes(&mut buf, 4, record.validity.as_bytes());
232→    encode_proto_varint(&mut buf, 5, record.sequence);
233→    encode_proto_varint(&mut buf, 6, record.ttl);
234→
235→    let libp2p_pub_key = encode_libp2p_public_key(&record.public_key);
236→    encode_proto_bytes(&mut buf, 7, &libp2p_pub_key);
237→
238→    encode_proto_bytes(&mut buf, 8, &record.signature_v2);
239→    encode_proto_bytes(&mut buf, 9, &record.data);
240→
241→    Ok(buf)
242→}
243→
244→/// Encode a protobuf length-delimited (bytes) field.
245→fn encode_proto_bytes(buf: &mut Vec<u8>, field_number: u32, data: &[u8]) {
246→    encode_varint(buf, ((field_number as u64) << 3) | 2);
247→    encode_varint(buf, data.len() as u64);
248→    buf.extend_from_slice(data);
249→}
250→
251→/// Encode a protobuf varint field.
252→fn encode_proto_varint(buf: &mut Vec<u8>, field_number: u32, value: u64) {
253→    encode_varint(buf, ((field_number as u64) << 3) | 0);
254→    encode_varint(buf, value);
255→}
256→
257→/// Encode a varint (protobuf LEB128).
258→fn encode_varint(buf: &mut Vec<u8>, mut value: u64) {
259→    loop {
260→        let byte = (value & 0x7f) as u8;
261→        value >>= 7;
262→        if value == 0 {
263→            buf.push(byte);
264→            break;
265→        } else {
266→            buf.push(byte | 0x80);
267→        }
268→    }
269→}
270→

 1→//! Typed HTTP client for CipherBox API.
 2→//!
 3→//! Provides async functions for all CipherBox API endpoints
 4→//! used by the desktop app: auth, IPFS, IPNS, vault operations.
 5→//! Mirrors @cipherbox/api-client TypeScript package.
 6→
 7→pub mod auth;
 8→pub mod client;
 9→pub mod error;
10→pub mod ipfs;
11→pub mod ipns;
12→pub mod types;
13→
14→pub use client::ApiClient;
15→pub use error::ApiError;
16→pub use types::*;
17→

  1→//! HTTP client with auth header injection and desktop client type header.
  2→//!
  3→//! All requests include `X-Client-Type: desktop` header so the backend
  4→//! returns refresh tokens in the response body instead of cookies.
  5→
  6→use reqwest::{Client, Response};
  7→use serde::Serialize;
  8→use std::sync::Arc;
  9→use tokio::sync::RwLock;
 10→
 11→use crate::error::ApiError;
 12→
 13→/// HTTP client wrapper for CipherBox API communication.
 14→///
 15→/// Manages base URL, access token, and ensures all requests
 16→/// include the `X-Client-Type: desktop` header.
 17→pub struct ApiClient {
 18→    client: Client,
 19→    base_url: String,
 20→    access_token: Arc<RwLock<Option<String>>>,
 21→}
 22→
 23→impl ApiClient {
 24→    /// Create a new API client with the given base URL.
 25→    pub fn new(base_url: &str) -> Self {
 26→        let client = Client::builder()
 27→            .timeout(std::time::Duration::from_secs(120))
 28→            .connect_timeout(std::time::Duration::from_secs(10))
 29→            .build()
 30→            .expect("failed to initialize HTTP client");
 31→        Self {
 32→            client,
 33→            base_url: base_url.trim_end_matches('/').to_string(),
 34→            access_token: Arc::new(RwLock::new(None)),
 35→        }
 36→    }
 37→
 38→    /// Store the access token for authenticated requests.
 39→    pub async fn set_access_token(&self, token: String) {
 40→        let mut guard = self.access_token.write().await;
 41→        *guard = Some(token);
 42→    }
 43→
 44→    /// Read the current access token (used for session restore).
 45→    pub async fn get_access_token(&self) -> Option<String> {
 46→        self.access_token.read().await.clone()
 47→    }
 48→
 49→    /// Clear the access token (used on logout).
 50→    pub async fn clear_access_token(&self) {
 51→        let mut guard = self.access_token.write().await;
 52→        *guard = None;
 53→    }
 54→
 55→    /// Send an authenticated GET request to a relative API path.
 56→    pub async fn authenticated_get(&self, path: &str) -> Result<Response, ApiError> {
 57→        let url = format!("{}{}", self.base_url, path);
 58→        let token = self.access_token.read().await;
 59→
 60→        let mut builder = self
 61→            .client
 62→            .get(&url)
 63→            .header("X-Client-Type", "desktop");
 64→
 65→        if let Some(ref t) = *token {
 66→            builder = builder.bearer_auth(t);
 67→        }
 68→
 69→        Ok(builder.send().await?)
 70→    }
 71→
 72→    /// Send an authenticated POST request with a JSON body to a relative API path.
 73→    pub async fn authenticated_post<T: Serialize>(
 74→        &self,
 75→        path: &str,
 76→        body: &T,
 77→    ) -> Result<Response, ApiError> {
 78→        let url = format!("{}{}", self.base_url, path);
 79→        let token = self.access_token.read().await;
 80→
 81→        let mut builder = self
 82→            .client
 83→            .post(&url)
 84→            .header("X-Client-Type", "desktop")
 85→            .json(body);
 86→
 87→        if let Some(ref t) = *token {
 88→            builder = builder.bearer_auth(t);
 89→        }
 90→
 91→        Ok(builder.send().await?)
 92→    }
 93→
 94→    /// Send an unauthenticated POST request with a JSON body to a relative API path.
 95→    /// Used for login and refresh where no access token is available yet.
 96→    pub async fn post<T: Serialize>(
 97→        &self,
 98→        path: &str,
 99→        body: &T,
100→    ) -> Result<Response, ApiError> {
101→        let url = format!("{}{}", self.base_url, path);
102→        Ok(self
103→            .client
104→            .post(&url)
105→            .header("X-Client-Type", "desktop")
106→            .json(body)
107→            .send()
108→            .await?)
109→    }
110→
111→    /// Fetch raw bytes from an absolute URL (used for IPFS content fetching).
112→    pub async fn get_bytes(&self, url: &str) -> Result<Vec<u8>, ApiError> {
113→        let resp = self.client.get(url).send().await?;
114→        let bytes = resp.bytes().await?;
115→        Ok(bytes.to_vec())
116→    }
117→
118→    /// Send an authenticated multipart POST request (used for IPFS file uploads).
119→    pub async fn authenticated_multipart_post(
120→        &self,
121→        path: &str,
122→        form: reqwest::multipart::Form,
123→    ) -> Result<Response, ApiError> {
124→        let url = format!("{}{}", self.base_url, path);
125→        let token = self.access_token.read().await;
126→
127→        let mut builder = self
128→            .client
129→            .post(&url)
130→            .header("X-Client-Type", "desktop")
131→            .multipart(form);
132→
133→        if let Some(ref t) = *token {
134→            builder = builder.bearer_auth(t);
135→        }
136→
137→        Ok(builder.send().await?)
138→    }
139→}
