  1→//! Authentication operations via the CipherBox backend API.
  2→//!
  3→//! Provides login, refresh, logout, and vault operations.
  4→
  5→use crate::client::ApiClient;
  6→use crate::error::ApiError;
  7→use crate::types::*;
  8→
  9→/// Log in to the CipherBox backend.
 10→///
 11→/// POST /auth/login with Web3Auth id_token and secp256k1 public key.
 12→/// Returns access and refresh tokens.
 13→pub async fn login(client: &ApiClient, request: &LoginRequest) -> Result<LoginResponse, ApiError> {
 14→    let resp = client.post("/auth/login", request).await?;
 15→
 16→    if !resp.status().is_success() {
 17→        let status = resp.status().as_u16();
 18→        let body = resp.text().await.unwrap_or_default();
 19→        return Err(ApiError::AuthFailed(format!(
 20→            "Login failed ({}): {}",
 21→            status, body
 22→        )));
 23→    }
 24→
 25→    resp.json::<LoginResponse>()
 26→        .await
 27→        .map_err(|e| ApiError::DeserializationFailed(format!("Login response: {}", e)))
 28→}
 29→
 30→/// Refresh the access token using a refresh token.
 31→///
 32→/// POST /auth/refresh with the current refresh token.
 33→/// Returns new access and refresh tokens (rotation).
 34→pub async fn refresh(
 35→    client: &ApiClient,
 36→    request: &RefreshRequest,
 37→) -> Result<RefreshResponse, ApiError> {
 38→    let resp = client.post("/auth/refresh", request).await?;
 39→
 40→    if !resp.status().is_success() {
 41→        let status = resp.status().as_u16();
 42→        let body = resp.text().await.unwrap_or_default();
 43→        return Err(ApiError::AuthFailed(format!(
 44→            "Refresh failed ({}): {}",
 45→            status, body
 46→        )));
 47→    }
 48→
 49→    resp.json::<RefreshResponse>()
 50→        .await
 51→        .map_err(|e| ApiError::DeserializationFailed(format!("Refresh response: {}", e)))
 52→}
 53→
 54→/// Log out from the CipherBox backend.
 55→///
 56→/// POST /auth/logout (authenticated). Best-effort -- errors are logged
 57→/// but not propagated (matches web app pattern).
 58→pub async fn logout(client: &ApiClient) -> Result<(), ApiError> {
 59→    let resp = client.authenticated_post("/auth/logout", &()).await?;
 60→
 61→    if !resp.status().is_success() {
 62→        let status = resp.status().as_u16();
 63→        let body = resp.text().await.unwrap_or_default();
 64→        log::warn!("Logout returned non-success ({}): {}", status, body);
 65→    }
 66→
 67→    Ok(())
 68→}
 69→
 70→/// Fetch the current user's vault.
 71→///
 72→/// GET /vault returns the root IPNS name and TEE keys.
 73→pub async fn get_vault(client: &ApiClient) -> Result<VaultResponse, ApiError> {
 74→    let resp = client.authenticated_get("/vault").await?;
 75→
 76→    if !resp.status().is_success() {
 77→        let status = resp.status().as_u16();
 78→        let body = resp.text().await.unwrap_or_default();
 79→        return Err(ApiError::ApiResponse {
 80→            status,
 81→            message: format!("Get vault failed: {}", body),
 82→        });
 83→    }
 84→
 85→    resp.json::<VaultResponse>()
 86→        .await
 87→        .map_err(|e| ApiError::DeserializationFailed(format!("Vault response: {}", e)))
 88→}
 89→
 90→/// Initialize a new user's vault.
 91→///
 92→/// POST /vault/init with the owner's public key and root IPNS name.
 93→pub async fn init_vault(
 94→    client: &ApiClient,
 95→    request: &InitVaultRequest,
 96→) -> Result<(), ApiError> {
 97→    let resp = client.authenticated_post("/vault/init", request).await?;
 98→
 99→    if !resp.status().is_success() {
100→        let status = resp.status().as_u16();
101→        let body = resp.text().await.unwrap_or_default();
102→        return Err(ApiError::ApiResponse {
103→            status,
104→            message: format!("Init vault failed: {}", body),
