659→    /// Get all unresolved FilePointer inodes (for batch IPNS resolution).
660→    /// Returns Vec of (ino, file_meta_ipns_name).
661→    #[cfg(any(feature = "fuse", feature = "winfsp"))]
662→    pub fn get_unresolved_file_pointers(&self) -> Vec<(u64, String)> {
663→        self.inodes.values().filter_map(|inode| {
664→            match &inode.kind {
665→                InodeKind::File {
666→                    file_meta_ipns_name: Some(ipns_name),
667→                    file_meta_resolved: false,
668→                    ..
669→                } => Some((inode.ino, ipns_name.clone())),
670→                _ => None,
671→            }
672→        }).collect()
673→    }
674→
675→    /// Get unresolved FilePointer inodes scoped to a specific parent folder.
676→    /// Avoids retrying root-level or other-folder pointers with the wrong folder key.
677→    #[cfg(any(feature = "fuse", feature = "winfsp"))]
678→    pub fn get_unresolved_file_pointers_for_parent(&self, parent_ino: u64) -> Vec<(u64, String)> {
679→        self.inodes.values().filter_map(|inode| {
680→            if inode.parent_ino != parent_ino {
681→                return None;
682→            }
683→            match &inode.kind {
684→                InodeKind::File {
685→                    file_meta_ipns_name: Some(ipns_name),
686→                    file_meta_resolved: false,
687→                    ..
688→                } => Some((inode.ino, ipns_name.clone())),
689→                _ => None,
690→            }
691→        }).collect()
692→    }
