 1→//! Application state for CipherBox Desktop.
 2→//!
 3→//! Thread-safe state holding decrypted keys in memory, API client,
 4→//! and mount status. Delegates key material management to `cipherbox_sdk::KeyState`.
 5→//! Sensitive keys are zeroed on logout via `clear_keys()`.
 6→
 7→use std::sync::Arc;
 8→use tokio::sync::RwLock;
 9→
10→use cipherbox_sdk::KeyState;
11→
12→/// Channel sender type for triggering manual sync from the tray menu.
13→pub type SyncTrigger = tokio::sync::mpsc::Sender<()>;
14→
15→/// FUSE mount status for the system tray indicator.
16→#[derive(Debug, Clone, PartialEq)]
17→pub enum MountStatus {
18→    Unmounted,
19→    Mounting,
20→    Mounted,
21→    Error(String),
22→}
23→
24→/// Thread-safe application state shared across Tauri commands.
25→///
26→/// Key material is managed by `cipherbox_sdk::KeyState` (the `sdk` field).
27→/// Tauri-specific fields (mount status, sync trigger, dev key) stay here.
28→pub struct AppState {
29→    /// SDK key state (shared with sync daemon and FUSE).
30→    pub sdk: Arc<KeyState>,
31→
32→    /// Current FUSE mount status (Tauri-specific).
33→    pub mount_status: RwLock<MountStatus>,
34→
35→    /// Channel sender to trigger an immediate sync cycle from the tray "Sync Now" button.
36→    /// Set once the SyncDaemon is spawned. Uses std::sync::RwLock because the tray
37→    /// menu event handler is synchronous.
38→    pub sync_trigger: std::sync::RwLock<Option<SyncTrigger>>,
39→
40→    /// Hex-encoded secp256k1 private key for headless auth (debug builds only).
41→    /// Set via `--dev-key <hex>` CLI argument. Compiled out in release builds.
42→    pub dev_key: RwLock<Option<String>>,
43→}
44→
45→impl AppState {
46→    /// Create a new AppState with the given API base URL and optional dev key.
47→    pub fn new(api_base_url: &str, dev_key: Option<String>) -> Self {
48→        Self {
49→            sdk: Arc::new(KeyState::from_url(api_base_url)),
50→            mount_status: RwLock::new(MountStatus::Unmounted),
51→            sync_trigger: std::sync::RwLock::new(None),
52→            dev_key: RwLock::new(dev_key),
53→        }
54→    }
55→
56→    /// Zero all sensitive key material and reset authentication state.
57→    ///
58→    /// Delegates to `KeyState::clear()` for key zeroization, then clears
59→    /// Tauri-specific fields (dev_key).
60→    pub async fn clear_keys(&self) {
61→        // Delegate key material clearing to SDK
62→        self.sdk.clear().await;
63→
64→        // Clear Tauri-specific sensitive fields
65→        {
66→            use zeroize::Zeroize;
67→            let mut key = self.dev_key.write().await;
68→            if let Some(ref mut k) = *key {
69→                k.zeroize();
70→            }
71→            *key = None;
72→        }
73→    }
74→}
