 1→//! ECIES key wrapping using secp256k1.
 2→//!
 3→//! Uses the `ecies` Rust crate which is cross-compatible with the `eciesjs` npm package
 4→//! (same author: ecies/rs and ecies/js). Format: ephemeral_pubkey(65) || nonce(16) || tag(16) || ciphertext.
 5→
 6→use crate::error::CryptoError;
 7→
 8→/// secp256k1 uncompressed public key size in bytes (04 prefix + x + y coordinates).
 9→pub const SECP256K1_PUBLIC_KEY_SIZE: usize = 65;
10→
11→/// secp256k1 private key size in bytes.
12→pub const SECP256K1_PRIVATE_KEY_SIZE: usize = 32;
13→
14→/// ECIES minimum ciphertext size: ephemeral pubkey (65) + auth tag (16).
15→pub const ECIES_MIN_CIPHERTEXT_SIZE: usize = SECP256K1_PUBLIC_KEY_SIZE + 16;
16→
17→/// Wrap (encrypt) data using ECIES with secp256k1.
18→///
19→/// The `ecies` Rust crate and `eciesjs` npm package produce compatible output.
20→pub fn wrap_key(data: &[u8], recipient_public_key: &[u8]) -> Result<Vec<u8>, CryptoError> {
21→    // Validate public key size (uncompressed secp256k1)
22→    if recipient_public_key.len() != SECP256K1_PUBLIC_KEY_SIZE {
23→        return Err(CryptoError::InvalidPublicKey);
24→    }
25→
26→    // Validate uncompressed public key prefix (0x04)
27→    if recipient_public_key[0] != 0x04 {
28→        return Err(CryptoError::InvalidPublicKey);
29→    }
30→
31→    ecies::encrypt(recipient_public_key, data).map_err(|_| CryptoError::EciesWrappingFailed)
32→}
33→
34→/// Unwrap (decrypt) data using ECIES with secp256k1.
35→pub fn unwrap_key(wrapped: &[u8], private_key: &[u8]) -> Result<Vec<u8>, CryptoError> {
36→    // Validate private key size
37→    if private_key.len() != SECP256K1_PRIVATE_KEY_SIZE {
38→        return Err(CryptoError::InvalidPrivateKey);
39→    }
40→
41→    // Validate minimum ciphertext size
42→    if wrapped.len() < ECIES_MIN_CIPHERTEXT_SIZE {
43→        return Err(CryptoError::EciesUnwrappingFailed);
44→    }
45→
46→    ecies::decrypt(private_key, wrapped).map_err(|_| CryptoError::EciesUnwrappingFailed)
47→}
48→

 1→//! Ed25519 key generation, signing, and verification.
 2→//!
 3→//! Used for IPNS record signing. Deterministic signatures are critical
 4→//! for cross-language test vector verification.
 5→
 6→use ed25519_dalek::{Signer, SigningKey, Verifier, VerifyingKey};
 7→use rand::rngs::OsRng;
 8→use zeroize::{Zeroize, Zeroizing};
 9→
10→use crate::error::CryptoError;
11→
12→/// Ed25519 public key size in bytes.
13→pub const ED25519_PUBLIC_KEY_SIZE: usize = 32;
14→
15→/// Ed25519 private key size in bytes.
16→pub const ED25519_PRIVATE_KEY_SIZE: usize = 32;
17→
18→/// Ed25519 signature size in bytes.
19→pub const ED25519_SIGNATURE_SIZE: usize = 64;
20→
21→/// Generate a new Ed25519 keypair.
22→///
23→/// Returns (public_key_32bytes, private_key_32bytes).
24→/// The private key is wrapped in `Zeroizing` to ensure it is zeroed on drop.
25→pub fn generate_ed25519_keypair() -> (Vec<u8>, Zeroizing<Vec<u8>>) {
26→    let signing_key = SigningKey::generate(&mut OsRng);
27→    let verifying_key = signing_key.verifying_key();
28→
29→    (
30→        verifying_key.to_bytes().to_vec(),
31→        Zeroizing::new(signing_key.to_bytes().to_vec()),
32→    )
33→}
34→
35→/// Sign a message with an Ed25519 private key.
36→///
37→/// Returns 64-byte deterministic signature.
38→pub fn sign_ed25519(message: &[u8], private_key: &[u8]) -> Result<Vec<u8>, CryptoError> {
39→    if private_key.len() != ED25519_PRIVATE_KEY_SIZE {
40→        return Err(CryptoError::InvalidPrivateKey);
41→    }
42→
43→    let mut key_bytes: [u8; 32] = private_key
44→        .try_into()
45→        .map_err(|_| CryptoError::InvalidPrivateKey)?;
46→    let signing_key = SigningKey::from_bytes(&key_bytes);
47→    key_bytes.zeroize();
48→    let signature = signing_key.sign(message);
49→
50→    Ok(signature.to_bytes().to_vec())
51→}
52→
53→/// Verify an Ed25519 signature.
54→///
55→/// Returns true if valid, false otherwise. Never throws.
56→pub fn verify_ed25519(message: &[u8], signature: &[u8], public_key: &[u8]) -> bool {
57→    if signature.len() != ED25519_SIGNATURE_SIZE || public_key.len() != ED25519_PUBLIC_KEY_SIZE {
58→        return false;
59→    }
60→
61→    let Ok(sig_bytes) = <[u8; 64]>::try_from(signature) else {
62→        return false;
63→    };
64→    let Ok(key_bytes) = <[u8; 32]>::try_from(public_key) else {
65→        return false;
66→    };
67→
68→    let Ok(verifying_key) = VerifyingKey::from_bytes(&key_bytes) else {
69→        return false;
70→    };
71→
72→    let sig = ed25519_dalek::Signature::from_bytes(&sig_bytes);
73→    verifying_key.verify(message, &sig).is_ok()
74→}
75→
76→/// Derive the 32-byte public key from a 32-byte Ed25519 private key.
77→pub fn get_public_key(private_key: &[u8]) -> Result<Vec<u8>, CryptoError> {
78→    if private_key.len() != ED25519_PRIVATE_KEY_SIZE {
79→        return Err(CryptoError::InvalidPrivateKey);
80→    }
81→
82→    let mut key_bytes: [u8; 32] = private_key
83→        .try_into()
84→        .map_err(|_| CryptoError::InvalidPrivateKey)?;
85→    let signing_key = SigningKey::from_bytes(&key_bytes);
86→    key_bytes.zeroize();
87→    let verifying_key = signing_key.verifying_key();
88→
89→    Ok(verifying_key.to_bytes().to_vec())
90→}
91→

  1→//! IPNS name derivation (CIDv1 base36 from Ed25519 public key).
  2→//!
  3→//! This module extracts only the pure IPNS name derivation logic.
  4→//! IPNS record creation/marshaling stays in the desktop app (or cipherbox-core)
  5→//! because it involves domain-specific types and CBOR/protobuf encoding.
  6→
  7→use crate::error::CryptoError;
  8→
  9→/// Encode the Ed25519 public key in libp2p PublicKey protobuf format.
 10→///
 11→/// message PublicKey { KeyType Type = 1; bytes Data = 2; }
 12→/// where KeyType.Ed25519 = 1
 13→pub fn encode_libp2p_public_key(ed25519_public_key: &[u8]) -> Vec<u8> {
 14→    let mut buf = Vec::new();
 15→    // Field 1 (Type): varint, field_number=1, wire_type=0 => tag = 0x08
 16→    buf.push(0x08);
 17→    // Value: 1 (Ed25519)
 18→    buf.push(0x01);
 19→    // Field 2 (Data): length-delimited, field_number=2, wire_type=2 => tag = 0x12
 20→    buf.push(0x12);
 21→    // Length of public key (32 bytes)
 22→    buf.push(ed25519_public_key.len() as u8);
 23→    buf.extend_from_slice(ed25519_public_key);
 24→    buf
 25→}
 26→
 27→/// Derive the IPNS name (CIDv1 base36) from an Ed25519 public key.
 28→///
 29→/// Steps:
 30→/// 1. Wrap public key in libp2p PublicKey protobuf
 31→/// 2. Create identity multihash: 0x00 (identity) + varint(len) + data
 32→/// 3. Create CIDv1: version=1, codec=0x72 (libp2p-key), multihash
 33→/// 4. Encode as base36 (k... prefix)
 34→pub fn derive_ipns_name(ed25519_public_key: &[u8; 32]) -> Result<String, CryptoError> {
 35→    // Step 1: Wrap in libp2p PublicKey protobuf
 36→    let libp2p_pub_key = encode_libp2p_public_key(ed25519_public_key);
 37→
 38→    // Step 2: Create identity multihash
 39→    // Identity multihash: code=0x00, length=varint(data.len()), data
 40→    let mut identity_multihash = Vec::new();
 41→    identity_multihash.push(0x00); // identity hash function code
 42→    // Encode length as unsigned varint
 43→    encode_unsigned_varint(&mut identity_multihash, libp2p_pub_key.len() as u64);
 44→    identity_multihash.extend_from_slice(&libp2p_pub_key);
 45→
 46→    // Step 3: Create CIDv1
 47→    // CIDv1 binary: version(1) + codec(0x72, libp2p-key) + multihash
 48→    let mut cid_bytes = Vec::new();
 49→    encode_unsigned_varint(&mut cid_bytes, 1); // CID version 1
 50→    encode_unsigned_varint(&mut cid_bytes, 0x72); // libp2p-key codec
 51→    cid_bytes.extend_from_slice(&identity_multihash);
 52→
 53→    // Step 4: Encode as base36 with 'k' prefix
 54→    let base36 = encode_base36(&cid_bytes);
 55→    Ok(format!("k{}", base36))
 56→}
 57→
 58→/// Encode unsigned varint (same as protobuf varint / LEB128).
 59→fn encode_unsigned_varint(buf: &mut Vec<u8>, mut value: u64) {
 60→    loop {
 61→        let byte = (value & 0x7f) as u8;
 62→        value >>= 7;
 63→        if value == 0 {
 64→            buf.push(byte);
 65→            break;
 66→        } else {
 67→            buf.push(byte | 0x80);
 68→        }
 69→    }
 70→}
 71→
 72→/// Encode bytes as base36 (lowercase).
 73→///
 74→/// Base36 alphabet: REDACTED
 75→fn encode_base36(data: &[u8]) -> String {
 76→    if data.is_empty() {
 77→        return String::new();
 78→    }
 79→
 80→    const ALPHABET: &[u8; 36] = b"REDACTED";
 81→
 82→    // Count leading zeros
 83→    let leading_zeros = data.iter().take_while(|&&b| b == 0).count();
 84→
 85→    // Convert byte array to big integer using repeated division
 86→    let mut num = data.to_vec();
 87→    let mut result = Vec::new();
 88→
 89→    while !num.is_empty() {
 90→        let mut remainder: u32 = 0;
 91→        let mut quotient = Vec::new();
 92→
 93→        for &byte in &num {
 94→            let acc = (remainder << 8) | (byte as u32);
 95→            let digit = acc / 36;
 96→            remainder = acc % 36;
 97→
 98→            if !quotient.is_empty() || digit > 0 {
 99→                quotient.push(digit as u8);
100→            }
101→        }
102→
103→        result.push(ALPHABET[remainder as usize]);
104→        num = quotient;
105→    }
106→
107→    // Add leading '0's for each leading zero byte
108→    for _ in 0..leading_zeros {
109→        result.push(b'0');
110→    }
111→
112→    result.reverse();
113→    String::from_utf8(result).unwrap_or_default()
114→}
