106→/// Format a timestamp as RFC3339 with nanosecond precision matching the ipns npm package.
107→///
108→/// The ipns package uses format: "2026-02-08T23:31:12.138000000Z"
109→fn format_validity_timestamp(validity_time: SystemTime) -> String {
110→    let duration = validity_time
111→        .duration_since(UNIX_EPOCH)
112→        .unwrap_or(Duration::ZERO);
113→    let secs = duration.as_secs();
114→    let nanos = duration.subsec_nanos();
115→
116→    let days = secs / 86400;
117→    let time_of_day = secs % 86400;
118→    let hours = time_of_day / 3600;
119→    let minutes = (time_of_day % 3600) / 60;
120→    let seconds = time_of_day % 60;
121→
122→    let (year, month, day) = civil_from_days(days as i64);
123→
124→    format!(
125→        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:09}Z",
126→        year, month, day, hours, minutes, seconds, nanos
127→    )
128→}
129→
130→/// Convert days since Unix epoch to (year, month, day).
131→/// Algorithm from Howard Hinnant's civil_from_days.
132→fn civil_from_days(days: i64) -> (i64, u32, u32) {
133→    let z = days + 719468;
134→    let era = if z >= 0 { z } else { z - 146096 } / 146097;
135→    let doe = (z - era * 146097) as u64;
136→    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
137→    let y = (yoe as i64) + era * 400;
138→    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
139→    let mp = (5 * doy + 2) / 153;
140→    let d = doy - (153 * mp + 2) / 5 + 1;
141→    let m = if mp < 10 { mp + 3 } else { mp - 9 };
142→    let y = if m <= 2 { y + 1 } else { y };
143→    (y, m as u32, d as u32)
144→}
