146→/// Compute the V1 signature.
147→///
148→/// Per IPNS spec, V1 signature is over: value_bytes + validity_bytes + varint(validityType)
149→fn compute_v1_signature(
150→    ed25519_private_key: &[u8; 32],
151→    value: &str,
152→    validity: &str,
153→) -> Result<Vec<u8>, IpnsError> {
154→    let mut data_to_sign = Vec::new();
155→    data_to_sign.extend_from_slice(value.as_bytes());
156→    data_to_sign.extend_from_slice(validity.as_bytes());
157→    data_to_sign.push(0x00);
158→
159→    sign_ed25519(&data_to_sign, ed25519_private_key).map_err(|_| IpnsError::SigningFailed)
160→}
