[package]
name = "cipherbox-desktop"
version = "0.1.0"
edition = "2021"

[features]
default = ["fuse"]
fuse = ["cipherbox-fuse/fuse", "dep:fuser", "dep:unicode-normalization"]
winfsp = ["cipherbox-fuse/winfsp", "dep:winfsp", "dep:widestring"]

[dependencies]
# Internal crates
cipherbox-crypto = { workspace = true }
cipherbox-core = { workspace = true }
cipherbox-api-client = { workspace = true }
cipherbox-fuse = { workspace = true }
cipherbox-sdk = { workspace = true }

# Tauri
tauri = { version = "2", features = ["tray-icon", "image-png", "image-ico"] }
tauri-plugin-deep-link = "2"
tauri-plugin-autostart = "2"
tauri-plugin-shell = "2"
tauri-plugin-notification = "2"

# FUSE
fuser = { version = "0.16", default-features = false, features = ["libfuse"], optional = true }

# System
keyring = { version = "3", features = ["apple-native", "windows-native", "linux-native-sync-persistent"] }
dirs = "5"
env_logger = "0.11"
clap = { version = "4", features = ["derive"] }
dotenvy = "0.15"
unicode-normalization = { version = "0.1.25", optional = true }

# Encoding (non-crypto, domain-specific)
multihash = "0.19"
unsigned-varint = "0.8"
urlencoding = "2"

# Workspace dependencies
ecies = { workspace = true }
reqwest = { workspace = true }
tokio = { workspace = true }
serde = { workspace = true }
serde_json = { workspace = true }
hex = { workspace = true }
base64 = { workspace = true }
log = { workspace = true }
thiserror = { workspace = true }
zeroize = { workspace = true }
rand = { workspace = true }
sha2 = { workspace = true }
ed25519-dalek = { workspace = true }

# Windows-only
winfsp = { version = "0.12", optional = true, features = ["system"] }
widestring = { version = "1", optional = true }

[target.'cfg(windows)'.dependencies]
winreg = "0.55"

[target.'cfg(unix)'.dependencies]
libc = "0.2"

[target.'cfg(windows)'.build-dependencies]
winfsp = "0.12"

[dev-dependencies]
ciborium = { workspace = true }

[build-dependencies]
tauri-build = { version = "2", features = [] }

